<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api/client'
import type { Profile } from '../api/contracts'
import { useProfileDraft } from '../composables/useProfileDraft'
const router = useRouter(), { resetDraft } = useProfileDraft()
const profiles = ref<Profile[]>([]), error = ref(''), loading = ref(true)
const validProfiles = computed(() => profiles.value.filter(item => item.valid))
const risky = (profile: Profile) => Boolean(profile.policy?.allow_network || profile.policy?.allow_model || profile.policy?.allow_git || profile.policy?.allow_publish || profile.policy?.allow_deploy)
function createProfile() { resetDraft(); router.push('/profile-composer/form') }
async function refresh() { loading.value = true; error.value = ''; try { profiles.value = (await api.profiles()).profiles } catch (e) { error.value = e instanceof Error ? e.message : '无法读取 Profile 库' } finally { loading.value = false } }
onMounted(refresh)
</script>
<template><section class="page profile-library"><div class="page-heading"><div><p class="eyebrow">REGISTERED PROFILE LIBRARY</p><h1>Profile 库</h1><p>这里列出服务端已注册并通过运行时校验的 Profile。新建 Profile 先进入草稿编排与纯预检；预检通过后可直接保存，是否可执行仍由组件组合与 Policy 决定。</p></div><div class="library-actions"><button class="quiet-button" @click="router.push('/profile-components')">组件配置中心</button><button class="primary-button" @click="createProfile">+ 添加 Profile</button></div></div><p v-if="error" class="data-warning">⚠ {{ error }}</p><section class="library-summary"><article><b>{{ validProfiles.length }}</b><span>已校验 Profile</span></article><article><b>{{ profiles.length - validProfiles.length }}</b><span>无效或不可加载</span></article><article><b>{{ validProfiles.filter(risky).length }}</b><span>声明外部权限</span></article></section><p v-if="loading" class="empty-state">正在读取服务端 Profile 库…</p><section v-else-if="profiles.length" class="profile-grid"><article v-for="profile in profiles" :key="profile.id" class="workspace-panel profile-card" :class="{ invalid: !profile.valid }"><div class="profile-card-head"><div><span :class="profile.valid ? 'passed' : 'failed'">{{ profile.valid ? '已校验' : '不可用' }}</span><h2>{{ profile.ref || profile.id }}</h2></div><span v-if="risky(profile)" class="risk-chip">外部权限</span></div><p>{{ profile.description || '未提供描述' }}</p><template v-if="profile.valid"><div class="profile-chain"><span>{{ profile.source }}</span><i>→</i><span>{{ profile.compiler }}</span><i>→</i><span>{{ profile.maker }}</span><i>→</i><span>{{ profile.checkers?.join(' + ') }}</span><i>→</i><span>{{ profile.delivery }}</span></div><div class="profile-policy"><span>网络 {{ profile.policy?.allow_network ? '允许' : '禁止' }}</span><span>模型 {{ profile.policy?.allow_model ? '允许' : '禁止' }}</span><span>发布 {{ profile.policy?.allow_publish ? '允许' : '禁止' }}</span></div></template><p v-else class="data-warning">{{ profile.error || '服务端运行时校验未通过' }}</p><footer><button class="quiet-button" @click="router.push('/profile-components')">查看组件</button><button class="quiet-button" @click="createProfile">基于组件新建</button></footer></article></section><section v-else class="workspace-panel empty-state"><h2>还没有已注册 Profile</h2><p>请先添加草稿、完成预检并保存；保存成功后会立即注册为正式 Profile。</p><button class="primary-button" @click="createProfile">添加第一个 Profile</button></section><section class="workspace-panel library-boundary"><h2>当前边界</h2><p>Profile 库只展示服务端 `profiles/*.json` 中已注册的配置。Composer 草稿必须经过纯预检并显式保存后才会出现在这里，避免未保存草稿被误当作正式 Profile。</p></section></section></template>
<style scoped>.library-actions{display:flex;gap:9px;align-items:center}.library-actions .quiet-button{margin:0}.library-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:14px}.library-summary article{padding:15px;border:1px solid var(--line);border-radius:11px;background:color-mix(in srgb,var(--panel) 88%,transparent)}.library-summary b,.library-summary span{display:block}.library-summary b{font-size:23px}.library-summary span{margin-top:3px;color:var(--soft);font-size:10px}.profile-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.profile-card{display:flex;flex-direction:column;min-height:255px}.profile-card.invalid{border-color:color-mix(in srgb,var(--red) 45%,var(--line))}.profile-card-head{display:flex;justify-content:space-between;gap:10px}.profile-card h2{margin:10px 0 0;font-size:17px}.profile-card>p{color:var(--muted);font-size:12px}.risk-chip{height:max-content;padding:4px 6px;border-radius:6px;background:color-mix(in srgb,var(--amber) 13%,transparent);color:var(--amber);font-size:10px}.profile-chain{display:flex;gap:5px;flex-wrap:wrap;margin:12px 0;color:var(--blue);font:10px ui-monospace,SFMono-Regular,Menlo,monospace}.profile-chain i{color:var(--soft);font-style:normal}.profile-policy{display:flex;gap:7px;flex-wrap:wrap}.profile-policy span{padding:4px 6px;border-radius:5px;background:var(--panel-2);color:var(--soft);font-size:10px}.profile-card footer{display:flex;gap:8px;margin-top:auto;padding-top:15px}.profile-card footer .quiet-button{margin:0}.library-boundary{margin-top:14px}.library-boundary h2{margin:0;font-size:13px}.library-boundary p{margin:7px 0 0;color:var(--muted);font-size:12px}@media(max-width:700px){.library-actions{align-items:stretch;flex-direction:column}.library-summary,.profile-grid{grid-template-columns:1fr}}</style>
